WITH payload AS (SELECT $archive_payload$[{"id":"a9344699-2d76-5cf2-b8e0-7ca4618ceb4d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -اعتداء على أحد األشخاص بالضرب -عدم احلد برائحة املسكر احلدود تدرأ بالشبهات -تداخل العقوبات التعزيرية -التعزير باجللد .","document_number":"34285497","case_number":"34121921","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/2","year":"1434","subject":"مسكر -شرب املسكر -اعتداء على أحد األشخاص بالضرب -عدم احلد برائحة املسكر احلدود تدرأ بالشبهات -تداخل العقوبات التعزيرية -التعزير باجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"          ‫رقم الصك‪ 34285497‬تاريخه‪1434/8/2 :‬هـ‬\n                          ‫رقم الدعوى‪34121921:‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n      ‫االستئناف‪ 342497172:‬تاريخه‪1434/12/23:‬هـ‬\n\n\n       ‫مســكر ‪ -‬شــرب املســكر ‪ -‬اعتــداء علــى أحــد األشــخاص بالضــرب ‪ -‬عــدم‬\n       ‫احلــد برائحــة املســكر احلــدود تــدرأ بالشــبهات ‪ -‬تداخــل العقوبــات‬\n                                              ‫التعزيريــة ‪ -‬التعزيــر باجللــد ‪.‬‬\n\n\n\n\n       ‫‪ -1‬مــا نــص عليــه أهــل العلــم مــن أنــه يثبــت شــرب املســكر بإقــرار الشــارب‬\n       ‫أو بشــهادة رجلــن عدلــن يشــهدان أنــه شــرب املســكر (كشــاف القنــاع‬\n                                                                               ‫‪. )101/14‬‬\n       ‫‪ -2‬مــا نــص عليــه أهــل العلــم مــن أنــه ال يحــد بوجــود رائحــة اخلمــر‬\n       ‫منــه الحتمــال أنــه متضمــض بهــا أو ظنهــا مــاء فلمــا صــارت يف فيــه‬\n       ‫مجهــا ونحــو ذلــك واحلــد يــدرأ بالشــبهة لكــن يعــزر كحاضــر شــربها‬\n                                                         ‫(كشــاف القنــاع ‪. )101/14‬‬\n               ‫‪ -3‬ما نص عليه أهل العلم من أن العقوبات التعزيرية تتداخل‬\n                                                           ‫(كشاف القناع ‪. )113/14‬‬\n\n\n\n\n       ‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا باالعتــداء علــى أحــد‬\n       ‫األشــخاص بالضــرب وشــرب املســكر ‪،‬وطلــب إثبــات مــا أســند إليهمــا‬\n       ‫واحلكــم عليهمــا بحــد املســكر وتعزيرهمــا لقــاء االعتــداء‪ ،‬حيــث‬\n\n‫‪171‬‬\n\f‫لوحــظ املدعــى عليهمــا يقومــان بضــرب أحــد األشــخاص وبحضــور‬\n‫الدوريــة األمنيــة اتضــح بأنهمــا بحالــة غيــر طبيعيــة فتــم التحفــظ عليهمــا‬\n‫‪،‬وباستشــمامهما اتضــح انبعــاث رائحــة املســكر منهما‪،‬وحضــر أحــد‬\n‫املدعــى عليهمــا (أجنبــي) يتكلــم اللغــة العربية‪،‬وأنكــر الدعوى ‪،‬وبناء‬\n‫علــى مــا تقــدم حكمــت احملكمــة بتعزيــر املدعــى عليــه بجلــده ســبعني‬\n‫جلــدة لتوجــه تهمــة شــرب املســكر وتهمــة االعتــداء بالضــرب ‪،‬لتداخــل‬\n‫العقوبــات التعزيرية‪،‬وقنــع املدعــى عليــه ‪،‬واعتــرض املدعــي العــام بــدون‬\n                      ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬     ‫الئحــة ُ‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد ففــي يــوم االثنــن املوافــق ‪1434/8/1‬ه ـ لــدي أنــا‬\n‫ـاء علــى املعاملــة احملالــة‬\n                           ‫‪ .....‬القاضــي باحملكمــة اجلزائيــة بالدمــام وبنـ ً‬\n‫إلينــا مــن رئيــس احملكمــة برقــم (‪ )34121921‬وتاريــخ ‪1434/3/15‬ه ـ‬\n‫افتتحــت اجللســة وفيهــا قــدم املدعــي العــام ‪.....‬الئحــة االدعــاء املتضمنــة‬\n‫بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام لفــرع الهيئــة باملنطقــة‬\n‫الشــرقية أدعــي علــى ‪.....‬باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة‬\n‫رقــم (‪ ).....‬و ‪.....‬باكســتاني اجلنســية مبوجــب رخصــة اإلقامــة رقــم‬\n‫(‪ ).....‬انــه بعــد االطــاع علــى محضــر تنفيــذ مهمــة واملتضمــن أنــه‬\n‫بتاريــخ ‪1434/2/23‬ه ـ مت مالحظــة املدعــى عليهمــا يقومــان بضــرب‬\n‫املدعــي‪..... /‬افضــل فتــم طلــب الدوريــات الرســمية وبحضــور الدوريــة‬\n‫الرســمية اتضــح بــأن املدعــى عليهمــا بحالــة غيــر طبيعيــة فتــم التحفــظ‬\n‫عليهمــا وبإستشــمام املدعــى عليهمــا املذكوريــن أتضــح انبعــاث رائحــة‬\n‫املســكر منهمــا وبســماع أقــوال املدعــي ‪.....‬املذكــور أفــاد بــأن املدعــى‬\n\n                                                                                     ‫‪172‬‬\n\f      ‫عليهمــا قامــا باالعتــداء عليــه بالضــرب بــا ســبب وباســتجواب املدعــى‬\n      ‫األول أفــاد بأنــه يعــرف املدعــي وأنــه صديــق وقريــب لــه ويطالبــه مببلــغ‬\n      ‫مالــي وهــذا ســبب تقــدمي شــكواه وباســتجواب املتهــم الثانــي أفــاد بأنــه‬\n      ‫طلــب مــن الشــرطة إحالتــه للمستشــفى إلثبــات أنــه لــم يشــرب املســكر‬\n      ‫ولكنهــم رفضــوا وقــد انتهــى التحقيــق معهمــا إلــى توجيــه االتهــام لهمــا‬\n      ‫باالعتــداء علــى أحــد األشــخاص بالضــرب وشــرب املســكر وذلــك‬\n      ‫لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا ورد مبحضــر تنفيــذ املهمــة املشــار‬\n      ‫إليــه واملتضمــن مالحظــة املتهمــن يقومــان بضــرب املدعــي واملرفــق‬\n      ‫لفــة رقــم (‪ -2 )2‬مــا ورد مبحضــر االستشــمام املنــوه عنــه واملــدون علــى‬\n      ‫ص(‪ )6‬مبحضــر االســتدالالت املرفــق لفــة رقــم (‪ )1‬وحيــث إن مــا أقــدم‬\n      ‫عليــه املدعــى عليهمــا املذكوريــن وهمــا بكامــل أهليتهمــا املعتبــرة‬\n      ‫شــرعا فعــل محــرم ومعاقــب عليــه شــرعا أطلــب إثبــات مــا اســند إليهمــا‬\n      ‫واحلكــم عليهمــا باآلتــي‪ -1 :‬حــد املســكر لقــاء شــربهما إيــاه ‪-2‬بعقوبــة‬\n      ‫تعزيريــة لقــاء اعتدائهمــا علــى أحــد األشــخاص بالضــرب تزجرهمــا‬\n      ‫وتــردع غيرهمــا وبــاهلل التوفيــق ويف اجللســة حضــر املدعــى عليــه ‪.....‬‬\n      ‫املــدون هويتــه أعــاه وبتــاوة الدعــوى العامــة عليــه وســؤاله اإلجابــة‬\n      ‫عليهــا أجــاب بلغــة عربيــة واضحــة بقولــه مــا ذكــره امل ــدعى العــام غيــر‬\n      ‫ال فأنــا لــم أشــرب املســكر ولــم أقــم بضــرب‬    ‫صح ــيح جملــة و تـفص ــي ً‬\n      ‫املدعــي ه ــذه إجـابت ــي و بســؤال املدعــى العــام عــن البينــة التــي تثبــت‬\n      ‫صحــة االدعــاء أجــاب بقولــة ليــس لــدي إال مــا يف أوراق ال ــمعاملة و قــد‬\n      ‫أشــرت إلــى األدلــة والقرائــن يف الئحــة االدع ــاء وعليــه جــرى االطــاع‬\n      ‫علــى محضــر االستشــمام املــدون علــى الصفحــة السادســة مــن ملــف‬\n      ‫التحقيــق واملتضمــن أنــه أثنــاء استشــمام املدعــى عليهمــا اتضــح انبعــاث‬\n\n\n‫‪173‬‬\n\f‫رائحــة املســكر منهــم كمــا جــرى االطــاع علــى محضــر تنفيــذ مهمــة‬\n‫املــدون علــى اللفــة الثانيــة واملتضمــن مالحظــة األشــخاص يقومــون‬\n‫بضــرب املدعــي واتضــح أن األشــخاص بحالــة ســكر وحالــة غيــر‬\n‫طبيعيــة كمــا جــرى االطــاع علــى ســوابق املدعــى عليــه املرفقــة بالئحة‬\n‫االدعــاء العــام واملتضمنــة عــدم وجــود ســوابق مســجلة عليــه فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى و اإلجابــة و حيــث أنكــر املدعــى عليــه صحــة مــا‬\n‫جــاء يف الئ ــحة االدعــاء ال ــعام و بنــاء ع ــلى مــا نــص عل ــيه أهــل العلــم مــن‬\n‫أنــه يـثـب ــت شــرب املســكر بإقــرار الشــارب أو بـشه ــادة رجـلـي ــن عدلـي ــن‬\n‫يـشه ــدان أنــه ش ــرب م ــسكراً(كشاف القنــاع ‪ )101/14‬وحيــث لــم‬\n‫يثبــت شــيء مــن ذلــك كمــا نــص أهــل العلــم علــى أنــه ال يـُح ــد بوج ــود‬\n‫رائح ــة الـخم ــر م ــنه الحتمــال أنــه متضمــض بهــا أو ظنهــا مــاء فلما صارت‬\n‫يف فيــه مجهــا ونحــو ذلــك واحلــد يــدرأ بالشــبهة لكــن يعــزر كحاضــر‬\n‫شــربها( كشــاف القنــاع ‪ ) 101/14‬و ع ــليه ف ــا يـثـب ــت حــد املســكر‬\n‫علــى املدعــى عليــه وبنــاء علــى محضــر االستشــمام ومحضــر تنفيــذ‬\n‫املهمــة املشــار إليهمــا أعــاه وحيــث إن العقوبــات التعزيريــة تتداخــل‬\n‫(كشــاف القنــاع‪ )113/14‬لــذا فقــد حـك ــمت بـجـل ــد املدعــى عليــه‬\n‫ســبعني جلــدة لتوجــه تهمــة شــرب املســكر وتهمــة االعتــداء بالضــرب‬\n‫ضــده و بعــرض احلكــم علــى املدعــى عليــه قــرر قناعتــه بــه وقــرر املدعــي‬\n‫العــام االعتــراض بالئحــة فأجيــب لطلبــه ومت تســليمه نســخة مــن احلكــم‬\n‫وأفهــم بتقــدمي االعتــراض عليــه خــال مهلــة ثالثــن يومــا وأنــه إذا انتهــت‬\n‫هــذه املهلــة ولــم يتقــدم باعتراضــه ســقط حقــه يف ذلــك وســوف يتــم‬\n‫رفــع احلكــم إلــى محكمــة االســتئناف بــدون الئحــة اعتراضيــة وبــاهلل‬\n‫التوفيــق وصلــى اهلل علــى نبينــا محمــد واملدعــي العــام علــى دعــواه ضــد‬\n\n\n                                                                                            ‫‪174‬‬\n\f      ‫املدعــى عليــه شــوكت علــي رحمــت اهلل علــي متــى مــا مت إحضــاره وبــه‬\n                                                                ‫حــرر يف ‪1434/8/1‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمة اجلزائيــة مبدينة الدمام برقم ‪34/643803‬‬\n      ‫وتاريــخ ‪1434/10/21‬ه ـ املقيــدة لــدى احملكمــة برقــم ‪34/2497172‬‬\n      ‫وتاريــخ ‪1434/11/4‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫الشــيخ ‪.....‬املســجل برقــم ‪ 34285497‬وتاريــخ ‪1434/8/2‬ه ـ اخلــاص‬\n      ‫بدعوى‪/‬املدعــى العــام ضــد‪..... -1/‬باكســتاني اجلنســية ‪..... -2‬‬\n      ‫باكســتاني اجلنســية يف قضيــة مضاربــه وشــرب مســكر وقــد تضمــن‬\n      ‫القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار‬\n      ‫وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم واهلل‬\n      ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‬\n                                                                         ‫‪1434/12/2‬ه ـ ‪.‬‬\n\n\n\n\n‫‪175‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":171,"source_page_end":175,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"095160b91be5831f14f6bcbb9a5644e028dd77f9716b003e52dc820e48883068","normalized_text_hash":"154ad7f2ec0136a2265a1cb2689782da3bdc50fd9749a164bb743ca8545aa297","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p171-34285497"},{"id":"3ccc7870-1f79-5f53-88ff-9f98ff7266d2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب مسكر -دخول منزل دون إذن صاحبه -رد دعوى املدعي العام لكون املدعى عليه فاق د لألهلية شرع ا -أمر قضائي بطلب الكشف الطبي النفسي على املدعى عليه -رد الدعوى .","document_number":"34245564","case_number":"34129606","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف بدون الئحة اعتراضية واهلل املوفق وصلى اهلل على نبينا محمد حرر يف 1434/6/7ه","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/18","year":"1434","subject":"مسكر -شرب مسكر -دخول منزل دون إذن صاحبه -رد دعوى املدعي العام لكون املدعى عليه فاق د لألهلية شرع ا -أمر قضائي بطلب الكشف الطبي النفسي على املدعى عليه -رد الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34245564:‬تاريخه ‪ 1434/03/18 :‬هـ‬\n                    ‫رقم الدعوى ‪34129606 :‬‬\n               ‫رقم قرار التصديق من محكمة‬\n   ‫االستئناف‪ 34265401:‬تاريخه‪1434/07/11:‬هـ‬\n\n\n  ‫مســكر ‪ -‬شــرب مســكر ‪ -‬دخــول منــزل دون إذن صاحبــه ‪ -‬رد دعــوى‬\n  ‫املدعــي العــام لكــون املدعــى عليــه فاقـ ٌـد لألهليــة شــرع ًا ‪ -‬أمــر قضائــي‬\n   ‫بطلــب الكشــف الطبــي النفســي علــى املدعــى عليــه ‪ -‬رد الدعــوى ‪.‬‬\n\n\n\n\n  ‫‪ -‬قولــه صلــى اهلل عليــه وســلم‪( :‬رفــع القلــم عــن ثــاث عــن الصبــي حتــى‬\n            ‫يبلــغ وعــن النائــم حتــى يســتيقظ وعــن املجنــون حتــى يفيق) ‪.‬‬\n\n\n\n\n  ‫انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه بشــرب املســكر‬\n  ‫وانتهــاك حرمــة منــزل مواطــن بالدخــول فيــه لغــرض ســيء ‪ ،‬طلــب‬\n                                    ‫املدعــي العــام احلكــم عليــه مبــا يلــي ‪:‬‬\n                                                ‫‪ -1‬بحد السكر لقاء شربه له‬\n  ‫‪ -2‬عقوبــة تعزيريــة لقــاء انتهاكــه حرمــة منزل أحــد املواطنني بالدخول‬\n                                                                             ‫فيه‬\n  ‫‪ -‬حضــر املدعــى عليــه ولوحــظ عليــه تصرفــات غيــر مســؤولة وكان‬\n  ‫كالمــه غيــر مترابــط ‪ ،‬متــت الكتابــة للكشــف عليــه طبي ـ ًا ملعرفــة‬\n  ‫مــدى أهليتــه العقليــة مــن عدمهــا‪ ،‬ورد التقريــر الطبــي املتضمــن أن‬\n  ‫املدعــى عليــه مصــاب باضطــراب ذهانــي وهــو بحالتــه الراهنــة غيــر‬\n                                                                                        ‫‪176‬‬\n\f      ‫مســؤول عــن تصرفاتــه‪ ،‬لكــون املدعــى عليــه غيــر مؤهــل شــرع ًا مت‬\n      ‫احلكــم بــرد دعــوى املدعــي العــام يف احلــق العــام‪ ،‬بعــرض احلكــم علــى‬\n      ‫املدعــي العــام قــرر معارضتــه علــى احلكــم بالئحــة اعتراضيــة وبعــد رفــع‬\n                           ‫احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األحــد بتاريــخ ‪1434/5/5‬ه ـ‬\n      ‫الســاعة التاســعة وخمســة عشــر دقيقــة افتتحــت اجللســة لــدي أنــا ‪.....‬بنــاء‬\n      ‫علــى املعاملــة احملالــة لــي مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالدمــام‬\n      ‫برقــم ‪ 34129606‬يف ‪1434/3/18‬ه ـ واملقيــدة بــوارد احملكمــة برقــم‬\n      ‫‪ 34686227‬يف ‪1434/3/18‬ه ـ وفيهــا حضــر املدعــي العــام وقــدم دعواه‬\n      ‫ا فيهــا أدعــي علــى ‪..... /‬هويــة رقــم ‪.....‬أنــه باالطــاع علــى محضــر‬     ‫قائ ـ ً‬\n      ‫تنفيــذ مهمــة املعــد مــن قبــل رجــال الدوريــة األمنيــة تبــن انــه عنــد الســاعة‬\n      ‫‪11‬م مــن يــوم الثالثــاء املوافــق ‪1434/1/27‬ه ـ وردهــم بالغ مــن العمليات‬\n      ‫عــن وجــود شــخص يبلــغ عــن قيــام شــخص بدخــول منزلــه بطريقــة غيــر‬\n      ‫شــرعية ومت تســليم األطــراف املدعــي (‪ ).....‬واملدعــى عليــه (‪ ).....‬لشــرطة‬\n      ‫‪.....‬وباستشــمام املدعــى عليــه‪ ...../‬مــن قبــل رجــال الضبــط اجلنائــي تبــن‬\n      ‫انبعــاث رائحــة املســكر مــن أنفاســه وبضبــط إفــادة املدعــي‪ ...../‬أفــاد‬\n      ‫ان (‪ ).....‬قــام بدفــع بــاب شــقته والدخــول فيهــا وكان بحالــة ســكر‬\n      ‫وبســماع اقــوال املدعــى عليه‪...../‬افــاد ان ســبب دخولــه املســكن للبحث‬\n      ‫عــن شــخص هنــدي اجلنســية كــي ينظــف منزلــه وباســتجواب املدعــى‬\n      ‫عليــه ‪/‬افــاد انــه طــرق بــاب الشــقة كونــه يبحــث عــن عامــل هنــدي‬\n      ‫وفجــأة فتــح البــاب بالكامــل واتــى صاحــب الشــقة واتهمــه بالدخــول‬\n\n‫‪177‬‬\n\f‫وشــرب املســكر وقــام بســحبه لداخــل الشــقة ثــم قــام باالتصــال علــى‬\n‫الدوريــة وانكــر معرفتــه باملدعــي وانتهــى التحقيــق إلــى توجيــه االتهــام‬\n‫للمدعــى عليــه بشــرب املســكر وانتهــاك حرمــة منــزل مواطــن بالدخــول‬\n                          ‫فيــه لغــرض ســيء وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪ -1‬مــا جــاء يف محضــر القبــض املتضمــن القبــض علــى املدعــى عليــه بعــد‬\n                                  ‫بــاغ املدعــي املنــوه عنــه واملرفــق لفــة رقــم( ‪)2‬‬\n‫‪ -2‬مــا جــاء يف بــاغ املدعــي وتطابقــه مــع مجمــل مــا اعتــرف بــه املدعــى‬\n‫عليــه املنــوه عنــه واملــدون علــى الصفحــة رقــم ( ‪ ) 1‬مــن دفتــر التحقيــق‬\n                                                                ‫املرفــق لفــة رقــم ( ‪)1‬‬\n‫‪ -3‬عــدم معرفــة املدعــى عليــه باملدعــي وتبريــره غيــر منطقــي لدخولــه‬\n‫املنــزل ببحثــه عــن شــخص ويف ســاعة متأخــرة مــن الليــل قرينــة علــى‬\n                                                                         ‫ســوء مقصــده‬\n‫‪ -4‬كــون املدعــى عليــه يف حالــة ســكر امــارة قويــة علــى قيامــه مبــا‬\n‫اتهــم بــه ‪ -5‬مــا جــاء يف إقــرار املدعــى عليــه بدخــول مســكن املدعــي‬\n‫للبحــث عــن شــخص هنــدي اجلنســية كــي ينظــف منزلــه املنــوه عنــه‬\n‫واملــدون علــى الصفحــة رقــم (‪ ) 10 - 9‬مــن دفتــر التحقيــق املرفــق لفــة‬\n                                 ‫رقــم (‪ ) 1‬ومــا دون علــى اللفــة رقــم( ‪)6 - 5‬‬\n‫‪ -6‬مــا جــاء يف محضــر االستشــمام املنــوه عنــه واملــدون علــى الصفحــة‬\n‫رقــم ( ‪ ) 6‬مــن دفتــر التحقــق املرفــق لفــة رقــم (‪ )1‬وحيــث إن مــا أقــدم‬\n‫عليــه املذكــور وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ‪ ،‬فعــل محـ ّـرم‬\n‫ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه مبــا‬\n                                                                                    ‫يلــي‪:‬‬\n‫‪ -1‬بحــد الســكر لقــاء شــربه لــه ‪ -2‬عقوبــة تعزيريــة تزجــره وتــردع غيره‬\n\n\n                                                                                             ‫‪178‬‬\n\f      ‫لقــاء انتهاكــه حرمــة منــزل احــد املواطنــن بالدخــول فيــه علمـ ًا بأن احلق‬\n      ‫اخلــاص ال يــزال قائمــا هــذه دعــواي أمــا املدعــى عليــه فقــد حضــر لنــا قبل‬\n      ‫موعــد اجللســة ولوحــظ عليــه تصرفــات غيــر مســئوله وكان كالمــه‬\n      ‫غيــر مترابــط فجــرى منــا إرســال خطــاب برقــم ‪ 34686227‬وتاريــخ‬\n      ‫‪1434/3/29‬ه ـ يف حينــه للكشــف عليــه طبي ـ ًا ملعرفــة مــدى أهليتــه‬\n      ‫العقليــة مــن عدمهــا فوردنــا تقريــر اللجنــة النفســية مبجمــع للصحــة‬\n      ‫النفســية بالدمــام رقــم ‪.....‬املتضمــن أنــه باالطــاع علــى ملــف املدعــى‬\n      ‫عليــه الطبــي وتقاريــر اللجنــة النفســية الصــادرة بحقــه تبــن أنــه مصــاب‬\n      ‫باضطــراب ذهانــي وهــو بحالتــه الراهنــة غيــر مســئول عــن تصرفاتــه يف‬\n      ‫القضيــة املنســوبة إليــه فبنــاء علــى مــا تقــدم مــن الدعــوى وباالطــاع علــى‬\n      ‫أوراق املعاملــة وبنــاء علــى مــا جــاء يف تقريــر اللجنــة النفســية مبجمــع‬\n      ‫للصحــة النفســية بالدمــام املشــار لرقمــه ومضمونــه بعاليــه ولكــون‬\n      ‫املدعــى عليــه غيــر مؤهــل شــرع ًا ولقولــه صلــى اهلل عليــه وســلم (رفــع‬\n      ‫القلــم عــن ثــاث عــن الصبــي حتــى يبلــغ وعــن النائــم حتــى يســتيقظ وعــن‬\n      ‫املجنــون حتــى يفيــق) لذلــك كلــه فقــد قــررت رد دعــوى املدعــي العــام‬\n      ‫يف احلــق العــام لعــدم أهليــة املدعــى عليــه شــرع ًا وبــه حكمــت وبعــرض‬\n      ‫ذلــك علــى املدعــي العــام قــرر معارضتــه علــى احلكــم بالئحــة اعتراضيــة‬\n      ‫فجــرى منــا تســليمه نســخة مــن احلكــم وأفهــم أن عليــه تقــدمي الالئحــة‬\n      ‫االعتراضيــة يف مــدة أقصاهــا يــوم االثنــن بتاريــخ ‪1434/6/5‬ه ـ وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n      ‫‪1434/5/5‬هــ‪ .‬ويف هــذا اليــوم األربعــاء املوافــق ‪1434/6/7‬ه ـ افتتحــت‬\n      ‫اجللســة يف متــام الســاعة الثانيــة عشــر وثالثــن دقيقــة ظهــرا ولــم يحضــر‬\n      ‫املدعــي العــام لتقــدمي الئحتــه االعتراضيــة علــى احلكــم الصــادر بحــق‬\n\n\n‫‪179‬‬\n\f‫املدعــى عليــه‪..... /‬برقــم ‪ 34205874‬وتاريــخ ‪1434/5/5‬ه ـ وحيــث إن‬\n‫املــدة النظاميــة لالعتــراض قــد انتهــت لــذا فقــد أمــرت ببعــث املعاملــة‬\n‫إلــى محكمــة االســتئناف بــدون الئحــة اعتراضيــة واهلل املوفــق وصلــى‬\n                          ‫اهلل علــى نبينــا محمــد حــرر يف ‪1434/6/7‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم االثنــن املوافــق ‪1434/8/1‬ه ـ‬\n‫افتتحــت اجللســة يف متــام الســاعة الواحــدة وخمســة عشــر دقيقــة ظهــرا‬\n‫بنــاء علــى ورود املعاملــة إلينــا مــن صاحــب الفضيلــة رئيــس محكمــة‬\n‫االســتئناف باملنطقــة الشــرقية بخطابــه رقــم ‪ 341539882‬وتاريــخ‬\n‫‪ 1434/7/16‬ه ـ واملقيــدة باحملكمــة برقــم‪ 341752011‬وبرفقهــا قــرار‬\n‫أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة الثانيــة رقــم ‪34265401‬‬\n‫وتاريــخ ‪1434/7/11‬ه ـ واملتضمــن املصادقــة علــى احلكــم ‪ ،‬وقــد‬\n‫أقفلــت اجللســة يف متــام الســاعة الواحــدة وثالثــن دقيقــة ظهــرا ‪ ،‬واهلل‬\n          ‫املوفــق وصلــى اهلل علــى نبينــا محمــد حــرر يف ‪1434/8/1‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                  ‫‪180‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":176,"source_page_end":180,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"25c3b8bbb4017ad727adcd00ca7b3ce54c7248c2c9ccf8dc1e3ab1367b613b98","normalized_text_hash":"89bd28caef90f8fd2d13d5eaba50ba0b0f63bf2d2a0e9f69943489cf90cd5786","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p176-34245564"},{"id":"8bb6ba9e-e42c-513c-b363-951da6f88f33","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -تكرار شرب املسكر -إقرار -حد املسكر - تعزير بالسجن واجللد على تكرار شرب املسكر .","document_number":"34266776","case_number":"34141620","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/12","year":"1434","subject":"مسكر -شرب املسكر -تكرار شرب املسكر -إقرار -حد املسكر - تعزير بالسجن واجللد على تكرار شرب املسكر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34266776:‬تاريخه‪1434/7/12:‬هـ‬\n                        ‫رقم الدعوى‪34141620 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34288431‬تاريخه‪1434/08/06:‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر ‪ -‬تكــرار شــرب املســكر ‪ -‬إقــرار ‪ -‬حــد املســكر ‪-‬‬\n                        ‫تعزيــر بالســجن واجللــد علــى تكــرار شــرب املســكر ‪.‬‬\n\n\n\n\n      ‫قــرار هيئــة كبــار العلمــاء ‪ 53‬يف ‪1397/4/4‬ه ـ ونصــه ( للقاضي أن يعزر‬\n      ‫مــن تكــرر منــه شــرب اخلمــر ثالثـ ًا وأقيــم عليــه احلــد بعــد كل مــرة مــن‬\n                          ‫ســجن وجلــد ونحوهمــا مــع إقامــة احلــد الواجــب ) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعى عليه بشــرب املســكر ‪،‬طلــب إثبات ما‬\n      ‫أســند إليــه واحلكــم عليــه بحــد املســكر وتعزيــره لقاء شــربه للمســكر‬\n      ‫أكثــر مــن ثــاث مــرات ولقــاء تعــدد ســوابقه ‪،‬حيــث قبــض علــى املدعــى‬\n      ‫عليــه مــن قبــل الدوريــات األمنيــة وذلــك باســتيقافهم ســيارة بقيــادة أحــد‬\n      ‫األشــخاص فــرزت لــه أوراق مســتقلة الســتكمال إجــراءات االســتدالل‬\n      ‫ويرافقــه املدعــى عليــه وكان فاقــد ًا للوعــي وكان بحالــة غيــر طبيعيــة‬\n      ‫‪،‬وأثبــت تقريــر الســموم الشــرعي إيجابيــة ســوائل املدعــى عليــه ملــادة‬\n      ‫اإليثيلــن ‪،‬وصــادق املدعــى عليــه علــى الدعــوى وعلــى الســوابق ‪،‬وبنــاء‬\n      ‫علــى مــا تقــدم حكمــت احملكمــة بجلــده ثمانــن جلــده دفعــة واحــدة‬\n      ‫حــد املســكر وتعزيــره لقــاء ســوابقه وتكــرر شــرب املســكر منــه‬\n‫‪181‬‬\n\f‫بســجنه أربعــة أشــهر وجلــده مائــة جلــدة مفرقــة علــى دفعتــن متســاويتني‬\n‫‪،‬وقنــع املدعــى عليــه باحلكــم واعتــرض املدعــي العــام مكتفيـ ًا بالئحــة‬\n                  ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬   ‫الدعــوى ُ‬\n\n\n\n‫اجلزائيــة‬\n   ‫ّ‬        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة‬\n‫باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة يف محافظــة االحســاء املكلــف برقــم ‪ 34141620‬وتاريــخ‬\n‫‪1434/03/25‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34752573‬وتاريــخ‬\n‫‪1434/03/25‬ه ـ ففــي يــوم األربعــاء املوافــق‪ 1434/07/12‬ه ـ افتتحت‬\n‫اجللســة األولــى الســاعة ‪ 11 : 15‬وفيهــا حضــر املدعــي العــام ‪.....‬املعمــد‬\n‫بحضــور جلســات احملكمــة مبوجــب خطــاب رئيــس دائــرة التحقيــق‬\n‫واالدعــاء العــام مبحافظــة االحســاء رقــم ‪.....‬وتاريــخ ‪1433/12/28‬ه ـ‬\n‫واحضــر معــه املدعــى عليــه ‪ .....‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪.....‬وادعــى املدعــي العــام قائــا يف دعــواه إنــه بتاريــخ‬\n‫‪1433/10/21‬ه ـ مت القبــض علــى املدعــى عليه مــن قبل رجال الدوريات‬\n‫األمنيــة مبحافظــة بقيــق إثــر إقامــة نقطــة تفتيــش وذلــك باســتيقافهم‬\n‫لســيارة مــن نــوع ‪ .......‬صنــع ( ‪ 1999‬م ) حتمــل اللوحــة رقــم ( ‪ ).....‬بقيــادة‬\n‫املدعــو ‪ (..... /‬فــرزت لــه أوراق مســتقلة وإحالتهــا لشــرطة محافظــة‬\n‫بقيــق الســتكمال إجــراءات االســتدالل ) ويرافقــه املدعــى عليــه الــذي‬\n‫كان يف حالــة غيــاب عــن الوعــي بســبب انخفــاض الســكر ‪ ،‬حيــث مت‬\n‫اســتدعاء الهــال األحمــر ونقلــه إلــى املستشــفى ‪ ،‬وقــد لوحــظ بأنــه يف‬\n‫حالــة غيــر طبيعيــة ( ســكر ) ‪ ،‬وقــد أثبــت تقريــر الســموم الشــرعية‬\n\n                                                                                       ‫‪182‬‬\n\f      ‫رقــم ( ‪.....‬لعــام ‪1434‬ه ـ ) إيجابيــة العينــة املرســلة لســوائل املدعــى عليــه‬\n      ‫ملــادة اإليثيلــن املســكرة ‪.‬وباســتجواب املدعــى عليــه أقــر بصحــة واقعــة‬\n      ‫القبــض عليــه وشــربه للمســكر يف ‪ ...............‬وقــد أســفر التحقيــق عــن‬\n      ‫توجيــه االتهــام لــه بشــرب املســكر ‪ ،‬وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n      ‫‪ -1‬إقــراره املــدون علــى الصفحــة رقــم ( ‪ ) 1‬مــن دفتــر التحقيــق لفــة رقــم‬\n                                                                                      ‫( ‪. ) 31‬‬\n                                        ‫‪ -2‬محضر القبض املرفق على لفة رقم ( ‪. ) 7‬‬\n      ‫‪ -3‬التقريــر الكيميائــي الشــرعي املرفــق علــى لفــة رقــم ( ‪) 28‬‬\n      ‫‪.‬وبالبحث عم ــا إذا ك ــان له سـ ــوابق مت العثور على ( ‪ ) 7‬ســبعة ســوابق‬\n      ‫مســجلة عليه اثنتان منها يف شــرب املســكر ‪ ،‬والثالثة شــرب املســكر‬\n      ‫وســرقة حيوانــات ‪ ،‬والرابعــة محاولــة لــواط ‪ ،‬واخلامســة شــرب املســكر‬\n      ‫وصــدم‪ ،‬والسادســة شــرب املســكر واالختــاء احملــرم ‪ ،‬والســابعة‬\n      ‫حيــازة واســتعمال املخــدرات وشــرب املســكر وحيازتــه ‪.‬وحيــث إن م ــا‬\n      ‫أقـ ــدم عليـ ــه املدعــى عليــه وهـ ــو بـك ــامل أهليتـ ــه املعتبــرة شرع ــ ًا ف ــعل‬\n      ‫مـح ــرم ومعـ ــاقب عليــه ش ــرع ًا ؛ أطلــب إثبــات مــا أســند إليــه ‪ ،‬واحلكــم‬\n                                                                             ‫عليــه باآلتــي‪:‬‬\n      ‫‪ -1‬بعقوبــة حــد املســكر لقــاء شــربه لــه ‪ -2.‬بعقوبــة تعزيريــة لقــاء شــربه‬\n      ‫املســكر أكثــر مــن ثــاث مــرات أقيــم عليــه احلــد يف كل مــرة ولــم‬\n      ‫يرتــدع ممــا يســتدعي التشــديد عليــه يف العقوبــة يف ضــوء قــرار هيئــة‬\n      ‫كبــار العلمــاء رقــم ( ‪ ) 53‬وتاريــخ ‪1397/4/4‬ه ـ ‪ ،‬ولقــاء تعــدد ســوابقه‬\n      ‫التــي لــم تردعــه عقوباتهــا اســتنا ًدا لتعميــم صاحــب الســمو نائــب وزيــر‬\n      ‫الداخليــة رقــم ( ‪ ) 93958/5/1‬وتاريــخ ‪1429/8/23‬ه ـ ‪.‬هــذه دعــواي‬\n      ‫وبعــرض الدعــوى علــى املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي‬\n\n\n‫‪183‬‬\n\f‫العــام صحيــح فقــد شــربت املســكر عامــدا عاملــا بتحرميــه وأنــا تائــب‬\n‫إلــى اهلل تعالــى ونــادم علــى مــا صــدر منــي والســوابق الســبع املشــار إليهــا‬\n‫صحيحــة هكــذا أجــاب وقــد اطلعــت علــى تقريــر الســموم الشــرعية‬\n‫الصــادر مــن املركــز اإلقليمــي ملراقبــة الســموم برقــم ‪.....‬فوجدتــه‬\n‫يتضمــن ايجابيــة عينــة دم املدعــى عليــه للمــواد الكحوليــة ‪ .‬فبنــاء علــى‬\n‫مــا ســلف مــن الدعــوى واإلجابــة وإقــرار املدعــى عليــه بشــربه للمســكر‬\n‫عامــدا عاملــا بتحرميــه وإقــراره بصحــة الســوابق املنســوبة إليــه وعقوبــة‬\n‫املســكر هــي احلــد ثمانــون جلــده وبنــاء علــى مطالبــة املدعــي العــام‬\n‫بتشــديد العقوبــة علــى املدعــى عليــه لقــاء تعــدد ســوابقه املشــار إليهــا‬\n‫أعــاه وبنــاء علــى مــا تضمنــه قــرار هيئــة كبــار العلمــاء ذي الرقــم ‪53‬‬\n            ‫والتاريــخ ‪1397/4/4‬ه ـ يف فقرتــه الرابعــة املتضمنــة مــا نصــه‬\n‫( للقاضــي أن يعــزر مــن تكــرر منــه شــرب اخلمــر ثالثــا وأقيــم احلــد عليــه‬\n‫بعــد كل مــره مــن ســجن وجلــد ونحوهمــا مــع إقامــة احلــد الواجــب) أه ـ‬\n‫وبنــاء علــى ذلــك كلــه فقــد قــررت مــا يلــي‪ :‬أوال ‪ /‬ثبــت لــدي شــرب‬\n‫املدعــى عليــه للمســكر وقــررت عقوبتــه بجلــده ثمانــن جلــده دفعــة‬\n‫واحــده حــدا للمســكر ‪ .‬ثانيــا ‪ /‬قــررت تعزيــر املدعــى عليــه لقــاء‬\n‫ســوابقه وتكــرر شــرب املســكر منــه أكثــر مــن ثــاث مــرات بســجنه‬\n‫ملــدة أربعــة اشــهر اعتبــارا مــن تاريــخ إيقافــه وجلــده مائــة جلــده مفرقــة‬\n‫علــى دفعتــن متســاويتني بــن كل منهــا مــدة ال تقــل عــن عشــرة أيــام‬\n‫مــع مراعــاة تلــك املــدة يف اجللــد املنصــوص عليــه يف الفقــرة األولــى ومبــا‬\n‫تقــدم حكمــت وبعرضــه علــى املدعــي العــام واملدعــى عليــه قــرر املدعــى‬\n‫عليــه قناعتــه بــه وقــرر املدعــي العــام عــدم القناعــة وطلــب االســتئناف‬\n‫مكتفيــا مبــا قــدم عــن تقــدمي الئحــة اعتراضيــه فأجبتــه لطلبــه وقــررت‬\n\n\n                                                                                        ‫‪184‬‬\n\f      ‫بعــث املعاملــة إلــى محكمــة االســتئناف باملنطقــة الشــرقية حســب‬\n      ‫التعليمــات وأقفلــت اجللســة الســاعة احلاديــة عشــر وخمســة وأربعــون‬\n      ‫دقيقــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه‬\n                                                       ‫وســلم حــرر يف ‪1434/7/12‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n      ‫لــدى احملكمــة برقــم ‪/34/1787253‬ج‪ 2‬وتاريــخ ‪1434/7/24‬ه ـ‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء‬\n      ‫املكلــف الشــيخ ‪ .....‬برقــم ‪ 341395435‬وتاريــخ ‪1434/7/19‬ه ـ املرفــق‬\n      ‫بهــا القــرار الصــادر مــن فضيلتــه املســجل برقــم ‪ 34266776‬وتاريــخ‬\n      ‫‪1434/7/12‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد‪.....‬يف قضيــة ســكر‬\n      ‫وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪.‬‬\n      ‫وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى‬\n      ‫احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n                                                               ‫حــرر يف ‪1434/8/6‬ه ـ ‪.‬‬\n\n\n\n\n‫‪185‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":181,"source_page_end":185,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ca5c292c1dbb6039cc7401702e885482b5ea6ab9dc7b48f9dda50c080bfcdefc","normalized_text_hash":"0c6e3c65312c63917680b33adc41dc702ab4bac29f2f5536c388339835e35d66","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p181-34266776"},{"id":"b943cf72-976b-5632-adfc-92cf3eb99790","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -قيادة السيارة حتت تأثير املسكر -ال يحد بوجود رائحة املسكر -درء احلدود بالشبهات -تداخل العقوبات التعزيرية -التعزير باجللد .","document_number":"34276384","case_number":"34170345","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/23","year":"1434","subject":"مسكر -شرب املسكر -قيادة السيارة حتت تأثير املسكر -ال يحد بوجود رائحة املسكر -درء احلدود بالشبهات -تداخل العقوبات التعزيرية -التعزير باجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 34276384 :‬تاريخه‪1434/7/23:‬هـ‬\n                   ‫رقم الدعوى‪34170345:‬‬\n             ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 3434503:‬تاريخه‪1434/10/28 :‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب املســكر ‪ -‬قيــادة الســيارة حتــت تأثيــر املســكر ‪ -‬ال يحــد‬\n‫بوجــود رائحــة املســكر ‪ -‬درء احلــدود بالشــبهات ‪ -‬تداخــل العقوبــات‬\n                                           ‫التعزيريــة ‪ -‬التعزيــر باجللــد ‪.‬‬\n\n\n\n\n‫‪ -1‬مــا نــص عليــه أهــل العلــم مــن أنــه يثبــت شــرب املســكر بإقــرار الشــارب‬\n‫أو بشــهادة رجلــن عدلــن يشــهدان أنــه شــرب املســكر ( كشــاف القنــاع‬\n                                                                        ‫‪. )101/14‬‬\n‫‪ -2‬مــا نــص عليــه أهــل العلــم مــن أنــه ال يحــد بوجــود رائحــة اخلمــر‬\n‫منــه الحتمــال أنــه متضمــض بهــا أو ظنهــا مــاء فلمــا صــارت يف فيــه‬\n‫مجهــا ونحــو ذلــك واحلــد يــدرأ بالشــبهة لكــن يعــزر كحاضــر شــربها‬\n                                                 ‫( كشــاف القنــاع ‪. )101/14‬‬\n‫‪ -3‬مــا نــص عليــه أهــل العلــم مــن أن العقوبــات التعزيريــة تتداخــل (‬\n                                                   ‫كشــاف القنــاع ‪. )113/14‬‬\n                                                        ‫‪ -4‬األصل براءة الذمة ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر والتلفــظ علــى‬\n‫أحــد موظفــي اجلمــارك واالعتــراض علــى اإلجــراءات وقيــادة املركبــة‬\n\n                                                                                       ‫‪186‬‬\n\f      ‫حتــت تأثيــر املســكر وطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد‬\n      ‫املســكر وتعزيــره لقــاء قيامــه بالتلفــظ واالعتــداء علــى موظــف اجلمارك‬\n      ‫‪،‬وإفهامــه بــأن عقوبتــه لقــاء قيــادة الســيارة عائــدة للجهــة املختصــة‬\n      ‫‪،‬حيــث قــدم املدعــى عليــه مــن ‪ ...............‬وهــو يقــود ســيارة وعنــد‬\n      ‫إجــراء التفتيــش اجلمركــي طلــب موظــف اجلمــارك مــن املدعــى عليــه‬\n      ‫النــزول مــن الســيارة لتفتيشــها واتضــح أنــه بحالــة غيــر طبيعيــة وبعــد‬\n      ‫االنتهــاء مــن تفتيــش الســيارة ركــب املدعــى عليــه فطلــب منــه موظــف‬\n      ‫اجلمــارك النــزول فرفــض النــزول وتلفــظ علــى املوظــف بالســب ثــم مت‬\n      ‫القبــض عليــه وباستشــمامه اتضــح انبعــاث رائحــة املســكر مــن أنفاســه‬\n      ‫‪،‬أنكــر املدعــى عليــه شــرب املســكر والتلفــظ علــى موظــف اجلمــارك‬\n      ‫وقيــادة الســيارة حتــت تأثيــر املســكر ‪،‬كمــا أقـ ّـر باالعتــراض علــى‬\n      ‫اإلجــراءات ‪،‬وال يوجــد للمدعــي العــام بينــة ســوى محضــر االستشــمام‬\n      ‫وتعــذر االســتجواب ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بتعزيــره‬\n      ‫للتهمــة بجلــده ســبعني جلــدة ‪،‬عــدم إثبــات إدانتــه بالتلفــظ علــى رجــل‬\n      ‫اجلمــارك أو قيــادة الســيارة حتــت تأثيــر املســكر ‪،‬رد دعــوى املدعــي‬\n      ‫العــام بهاتــن اجلزئيتــن وقنــع املدعــى عليــه باحلكــم واعتــرض املدعــي‬\n                    ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬     ‫العــام بالئحــة ُ‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1434/7/23‬ه ـ لــدي‬\n      ‫ـاء علــى املعاملــة احملالــة‬\n                                 ‫أنــا ‪.....‬القاضــي باحملكمــة اجلزائيــة بالدمــام وبنـ ً‬\n      ‫إلينــا مــن رئيــس احملكمــة برقــم (‪ )34170345‬وتاريــخ ‪1434/4/14‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــر ‪.....‬ســعودي اجلنســية مبوجــب الهويــة‬\n\n‫‪187‬‬\n\f‫الوطنيــة رقــم (‪ ).....‬وقــدم املدعــي العــام ‪.....‬الئحــة اإلدعــاء املتضمنــة‬\n‫بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام مبدينــة الدمــام أدعــي‬\n‫املذكــور أعــاه حيــث إنــه بتاريــخ ‪1434/2/3‬ه ـ قــدم املدعــى عليــه‬\n‫املذكــور مــن مملكــة البحريــن وكان يقــود مركبتــه مــن نــوع ‪...‬‬\n‫حتمــل اللوحــة رقــم (‪ ).....‬ســنة الصنــع (‪2011‬م) وعنــد إجــراء التفتيــش‬\n‫اجلمركــي طلــب موظــف اجلمارك‪...../‬ســعودي مبوجــب الهويــة الوطنيــة‬\n‫رقــم (‪ ).....‬مــن املدعــى عليــه النــزول مــن املركبــة لتفتيشــها و اتضــح أنــه‬\n‫يف حالــه غيــر طبيعيــة وبعــد االنتهــاء مــن تفتيــش املركبــة ركب املدعى‬\n‫عليــه املركبــة فطلــب منــه املوظــف النــزول مــرة ثانيــة بواســطة الكالب‬\n‫البوليســية فرفــض النــزول وتلفــظ املدعــى عليــه علــى املوظــف بقولــه‬\n‫(شــموه أنــت بــدل الــكالب) وعلــى ذلــك مت القبــض عليــه وباستشــمامه‬\n‫تبــن انبعــاث رائحــة املســكر مــن أنفاســه وباســتجوابه للمــرة األولــى‬\n‫تعــذر االســتجواب كونــه يف حالــة ســكر وباســتجوابه للمــرة الثانيــة‬\n‫أقــر بواقعــة القبــض و أنكــر شــرب املســكر والتلفــظ علــى موظــف‬\n‫اجلمــارك وقــد انتهــى التحقيــق إلــى اتهــام املدعــى عليــه املذكــور بشــرب‬\n‫املســكر واالعتــراض علــى االجــراءات والتلفــظ علــى احــد موظفــي‬\n‫اجلمــارك وقيــادة املركبــة حتــت تأثيــره وذلــك لألدلــة والقرائــن التاليــة‪:‬ـ‬\n‫‪ -1‬إقــراره املــدون علــى الصفحــة رقم(‪)10‬مــن ملــف االســتدالل املرفــق‬\n                                                                    ‫لفــه رقــم (‪)1‬‬\n‫‪ -2‬محضــر االستشــمام املــدون علــى الصفحــة رقــم (‪ )6‬مــن ملــف‬\n                                             ‫االســتدالل املرفــق لفــه رقــم (‪)1‬‬\n‫‪ -3‬مــا جــاء يف محضــر تعــذر االســتجواب املنــوه عنــه املرفــق بالصفحــة‬\n                               ‫(‪ )9‬مــن ملــف االســتدالل املرفــق لفــه رقــم (‪)1‬‬\n\n\n                                                                                       ‫‪188‬‬\n\f      ‫وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى ســوابق مســجلة وحيــث إن مــا‬\n      ‫أقــدم عليــه املدعــى عليــه ـ وهــو بكامــل أهليتــه املعتبــرة شــرعاً‪ -‬فعــل‬\n      ‫محــرم ومعاقــب عليــه شــرعاً‪ -‬أطلــب إثبــات مــا أســند إليــه واحلكــم‬\n                                                                        ‫عليــه مبــا يلــي‪:‬‬\n                                                    ‫‪ -1‬بحد املسكر لقاء شربه إياه‬\n      ‫‪ -2‬بعقوبــة تعزيريــة تزجــره وتــردع غيــره لقــاء قيامــه بالتلفــظ واالعتــداء‬\n                                             ‫علــى موظــف اجلمــارك أثنــاء أداء عملــه‬\n      ‫‪-3‬إثبــات إدانتــه بقيــادة املركبــة حتــت تأثيــر املســكر اســتنادا للفقــرة‬\n      ‫رقــم (‪ )8‬مــن اجلــدول رقــم (‪ )1‬امللحــق بنظــام املــرور وإفهامــه بــأن عقوبتــه‬\n      ‫الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )68‬مــن نظــام املــرور عائــدة‬\n      ‫للجهــة املختصــة وفقــا للفقــرة رقــم (‪ )2‬مــن قــرار مجلــس الــوزراء رقــم‬\n      ‫(‪ )315‬وتاريــخ ‪1428/10/24‬ه ـ وبــاهلل التوفيــق وبســؤال املدعــى عليــه‬\n      ‫أجــاب بقولــه مــا ذكــره املدعــي العــام مــن شــرب املســكر وقيــادة‬\n      ‫الســيارة حتــت تأثيــره و التلفــظ علــى أحــد موظفــي اجلمــارك فهــذا غيــر‬\n      ‫صحيــح جملــة وتفصيــا ومــا ذكــره مــن االعتــراض علــى االجــراءات‬\n      ‫فهــذا صحيــح و ذلــك أن موظــف اجلمــارك طلــب منــي النــزول مــن‬\n      ‫الســيارة للتفتيــش مرتــن فاســتجبت لــه ثــم طلــب منــي النــزول للمــرة‬\n      ‫الثالثــة رفضــت ذلــك هــذه إجابتــي وبســؤال املدعــي العــام عــن البينــة‬\n      ‫املثبتــة لصحــة التهمــة املنســوبة للمدعــى عليــه أجــاب بقولــه ليــس لــدي‬\n      ‫إال مــا يف أوراق املعاملــة ولقــد أشــرت إلــى األدلــة و القرائــن يف الئحــة‬\n      ‫االدعــاء وعليــه جــرى االطــاع علــى أقــوال املدعــى عليــه املدونــة علــى‬\n      ‫الصفحــة العاشــرة مــن ملــف التحقيــق فوجــدت فيهــا إنــكار املدعــى‬\n      ‫عليــه شــرب املســكر أو قيــادة الســيارة حتــت تأثيــره أو التلفــظ علــى‬\n\n\n‫‪189‬‬\n\f‫رجــل اجلمــارك بينمــا فيهــا إقــراره برفــض النــزول للتفتيــش حينمــا طلــب‬\n‫منــه موظــف اجلمــارك ذلــك للمــرة الثالثــة كمــا أن فيهــا إجابــة منــه بأنــه‬\n‫لــم يكــن يقــود الســيارة حــن القبــض عليــه و بعــرض ذلــك علــى املدعــى‬\n‫عليــه قــرر بقولــه نعــم هــذه األقــوال صحيحــة كمــا جــرى االطــاع علــى‬\n‫محضــر االستشــمام املــدون علــى الصفحــة السادســة مــن ملــف التحقيــق‬\n‫املتضمــن أنــه باستشــمام املدعــى عليــه تبــن أن رائحــة املســكر تنبعــث‬\n‫مــن أنفاســه كمــا جــرى االطــاع علــى محضــر تعــذر االســتجواب‬\n‫املــدون علــى الصفحــة التاســعة مــن ملــف التحقيــق واملتضمــن أنــه اتضــح‬\n‫أن املدعــى عليــه يف حالــة ســكر شــديد ولــم يفيــد التحقيــق معــه‬\n‫بشــيء ولــم أجــد أي بينــة تثبــت قيــام املدعــى عليــه بالتلفــظ علــى رجــل‬\n‫اجلمــارك أو أنــه كان يقــود الســيارة حــن القبــض عليــه واألصــل بــراءة‬\n‫الذمــة فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى‬\n‫عليــه بالقيــام باالعتــراض علــى إجــراءات التفتيــش واملــرء مؤاخــذ‬\n‫بإقــراره بينمــا أنكــر شــرب املســكر وقيــادة الســيارة حتــت تأثيــره‬\n‫والتلفــظ علــى رجــل اجلمــارك وبنــاء علــى محضــري واالستشــمام وتعــذر‬\n‫االســتجواب املشــار إليهــا أعــاه و بنــاء ع ــلى مــا نــص عل ــيه أهــل العلم من‬\n‫أنــه يـثـب ــت شــرب املســكر بإقــرار الشــارب أو بـشه ــادة رجـلـي ــن عدلـي ــن‬\n‫يـشه ــدان أنــه ش ــرب م ــسكراً(كشاف القنــاع ‪ )101/14‬وحيــث لــم‬\n‫يثبــت شــيء مــن ذلــك كمــا نــص أهــل العلــم علــى أنــه ال يـُح ــد بوج ــود‬\n‫رائح ــة الـخم ــر م ــنه الحتمــال أنــه متضمــض بهــا أو ظنهــا مــاء فلما صارت‬\n‫يف فيــه مجهــا ونحــو ذلــك واحلــد يــدرأ بالشــبهة لكــن يعــزر كحاضــر‬\n‫شربها(كشــاف القنــاع ‪ )101/14‬وحيــث إن العقوبــات التعزيريــة‬\n‫تتداخــل فيمــا بينها(كشــاف القنــاع‪ )113/14‬وع ــليه ف ــا يـثـب ــت حــد‬\n\n\n                                                                                       ‫‪190‬‬\n\f      ‫املســكر علــى املدعــى عليــه ويبقــى يف حقــه التعزيــر لقــاء توجــه التهمــة‬\n      ‫لــه بشــرب املســكر لــذا فقــد درأت حــد املســكر عــن املدعــى عليــه‬\n      ‫وثبــت لــدي إدانتــه باالعتــراض علــى إجــراءات التفتيــش وحكمــت‬\n      ‫بجلــده لقــاء ذلــك ولقــاء توجــه التهمــة ضــده بشــرب املســكر ســبعني‬\n      ‫جلــده ولــم يثبــت لــدي إدانتــه بقيــادة الســيارة حتــت تأثيــر املســكر أو‬\n      ‫التلفــظ علــى رجــل اجلمــارك وحكمــت بــرد دعــوى املدعــي العــام فيمــا‬\n      ‫يتعلــق بهاتــن اجلزئيتــن وبعــرض احلكــم علــى املدعــى عليــه قــرر قناعتــه‬\n      ‫بــه وقــرر املدعــي العــام االعتــراض بالئحــة فأجيــب لطلبــه ومت تســليمه‬\n      ‫نســخة مــن احلكــم وأفهــم بتقــدمي االعتــراض عليــه خــال مهلــة ثالثــن‬\n      ‫يومــا وأنــه إذا انتهــت هــذه املهلــة ولــم يتقــدم باعتراضــه ســقط حقــه يف‬\n      ‫ذلــك وســوف يتــم رفــع احلكــم إلــى محكمــة االســتئناف بــدون الئحــة‬\n      ‫اعتراضيــة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وبــه حــرر يف‬\n                                                                         ‫‪1434/7/23‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n      ‫لــدى احملكمــة برقــم ‪/34/2209871‬ج‪ 2‬وتاريــخ ‪1434/9/17‬ه ـ‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم‬\n      ‫‪ 34/908620‬وتاريــخ ‪1434/9/14‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشيخ‪...../‬املســجل برقــم ‪34276384‬‬\n      ‫وتاريــخ ‪1434/7/23‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪...../‬يف‬\n      ‫قضيــة مســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n      ‫املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                       ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/10/28‬ه ـ ‪.‬‬\n‫‪191‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":186,"source_page_end":191,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ce525060c9ffab671626a41ccf3cf7e62e74035e759db2156d28cd3227468f1b","normalized_text_hash":"3cb01380206c740c0659e9930450ba290f06353e9a0cab74c98e8cc94aa2bdcd","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p186-34276384"},{"id":"2ab8e261-01e9-5fb8-b188-efd58b3715e7","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حيازة بقصد الشرب -التعزير باجللد - اإلقرار حجة على املقر -األصل براءة الذمة -حد املسكر علن ا .","document_number":"34217683","case_number":"34176251","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/20","year":"1434","subject":"مسكر -شرب املسكر -حيازة بقصد الشرب -التعزير باجللد - اإلقرار حجة على املقر -األصل براءة الذمة -حد املسكر علن ا .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 34217683 :‬تاريخه‪1434/5/20 :‬هـ‬\n                    ‫رقم الدعوى‪34176251:‬‬\n              ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 34234557:‬تاريخه‪1434/06/07 :‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب املســكر ‪ -‬حيــازة بقصــد الشــرب ‪ -‬التعزيــر باجللــد ‪-‬‬\n‫اإلقــرار حجــة علــى املقــر ‪ -‬األصــل بــراءة الذمــة ‪ -‬حــد املســكر علن ـ ًا ‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه تعالــى ( إمنــا اخلمــر وامليســر واألنصــاب واألزالم رجــس مــن‬\n                        ‫عمــل الشــيطان فاجتنبــوه لعلكــم تفلحــون)‪.‬‬\n‫‪ -2‬قولــه صلــى اهلل عليــه وســلم (إن اهلل لعــن اخلمــر وعاصرهــا‬\n‫ومعتصرهــا وشــاربها وحاملهــا واحملمولــة إليــه) رواه احلاكــم ‪.‬‬\n‫‪ -3‬املــادة ‪ 128‬واملــادة ‪ 131‬مــن نظــام اإلجــراءات اجلزائيــة باختصــاص‬\n                                        ‫احملكمــة بنظــر هــذه الدعــوى ‪.‬‬\n‫‪ -4‬قــرار هيئــة كبــار العلمــاء ذي الرقــم ‪ 53‬يف ‪1397/4/4‬ه بــأن حــد‬\n                                                ‫شــرب املســكر ثمانــن ‪.‬‬\n                                               ‫‪ -5‬األصل براءة الذمة ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا بشــرب الثانــي للمســكر‬\n‫وحيازتــه بقصــد الشــرب وتســتر األول عليــه ‪،‬وطلــب إثبــات مــا أســند‬\n‫إليهمــا واحلكــم علــى الثانــي بحــد املســكر ‪،‬وعقوبــة تعزيريــة بحقهمــا‬\n‫لتســتر األول على الثاني وحليازة الثاني املســكر بقصد الشــرب ‪،‬حيث‬\n                                                                                     ‫‪192‬‬\n\f      ‫الحظــت دوريــة أمنيــة ســيارة بقيــادة املدعــى عليــه األول ويرافقــه املدعــى‬\n      ‫عليــه الثانــي وهــو بحالــة ســكر وبحوزتــه قــارورة حتتــوي علــى مســكر‬\n      ‫‪،‬وأثبــت التقريــر الكيميائــي الشــرعي إيجابيــة العينــة ملــادة الكحــول‬\n      ‫االيثيلــي ‪ ،‬وصــادق املدعــى عليــه الثانــي علــى الدعــوى ‪،‬وصــادق املدعــى‬\n      ‫عليــه األول علــى القبــض عليــه وهــو يقــود الســيارة ويرافقــه املدعــى‬\n      ‫عليــه األول وبحوزتــه قــارورة ‪،‬وأنكــر تســتره عليــه وأنــه ال يعلــم أن مــا‬\n      ‫بحوزتــه مســكر ‪،‬ومبــا أن اإلقــرار حجــة علــى املقــر ‪،‬وبنــاء علــى مــا‬\n      ‫تقــدم حكمــت احملكمــة علــى الثانــي بجلــده حــد املســكر ثمانــن‬\n      ‫جلــدة دفعــة واحــدة علن ـ ًا وجلــده تعزيــر ًا عشــرين جلــدة للحيــازة وبــراءة‬\n      ‫األول مــن التهمــة ‪،‬وقنــع املدعــى عليهمــا ‪،‬واعتــرض املدعــي العــام بــدون‬\n                             ‫وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬      ‫الئحــة ‪ُ ،‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬رئيــس احملكمــة اجلزائيــة‬\n      ‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة لنــا برقــم ‪34176251‬‬\n      ‫وتاريــخ ‪1434/04/16‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34939684‬وتاريــخ‬\n      ‫‪1434/04/16‬ه ـ ففــي يــوم االثنــن املوافــق‪ 1434/05/20‬ه ـ وفيهــا‬\n                     ‫حضــر املدعــي العــام ‪ .....‬كمــا حضــر املدعــى عليهمــا‪:‬‬\n      ‫‪..... -1‬ســعودي رقــم ســجله املدنــي (‪ ).....‬أعــزب ‪ ،‬عاطــل عــن العمــل‪،‬‬\n      ‫أوقــف بتاريــخ ‪1434/1/15‬ه ـ ‪ ،‬وأفــرج عنــه بتاريخ‪1434/1/20‬هــ‪،‬‬\n      ‫ويســكن القطيــف ‪.....-2‬ســعودي رقــم ســجله املدنــي (‪ ).....‬أعــزب‪،‬‬\n      ‫موظــف أهلــي ‪ ،‬أوقــف بتاريــخ ‪1434/1/15‬ه ـ ‪ ،‬وأفــرج عنــه بتاريــخ‬\n      ‫‪1434/12/20‬ه ـ ‪ ،‬ويســكن القطيــف ‪ .‬وقــدم األول الئحــة اتهــام‬\n\n‫‪193‬‬\n\f‫تتضمــن أنــه يف يــوم اخلميــس املوافــق ‪1434/1/15‬ه ـ وأثنــاء إقامــة‬\n‫نقطــة تفتيــش مت مالحظــة مركبــة بقيــادة املدعــى عليــه األول ويرافقــه‬\n‫املدعــى عليــه الثانــي وهــو بحالــة ســكر وبحوزتــه قــارورة مــاء صحــة‬\n‫حتتــوي علــى (‪ )100‬ملــم مــن املســكر وكأس بــه الربــع أثبــت التقريــر‬\n‫الكيمــاوي الشــرعي رقــم (‪ ).....‬احتوائهــا علــى مــادة الكحــول االيثيلــي‬\n‫وبنســبة مســكرة وباستشــمام املدعــى عليــه الثانــي تبــن أنــه بحالــة‬\n‫ســكر وباســتجواب املدعــى عليــه الثانــي (‪ )....‬أقــر بشــرب وحيــازة‬\n‫املســكر وبســماع أقــوال املدعــى عليــه األول (‪ ).....‬ذكــر بأنــه علــى‬\n‫علــم بــأن مرافقــه املدعــى عليــه الثانــي(‪ ).....‬كان بحالــه ســكر وقــد‬\n‫أســفر التحقيــق عــن اتهــام الثانــي بشــرب املســكر وحيازتــه لقــارورة‬\n‫مــاء صحــة بهــا رائحــة املســكر وكأس بــه الربــع مــن املســكر بقصــد‬\n‫الشــرب وتســتر األول عليــه ‪ ،‬وذلــك لألدلــة والقرائــن املوضحــة بالئحــة‬\n‫الدعــوى وبالبحــث عــن ســوابقهما عثــر لــأول علــى ســابقتي األولــى‬\n‫مخــدرات والثانيــة ســرقة ولــم يعثــر للثانــي علــى ســوابق جنائيــة مســجلة‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــوران وهمــا بكامــل أهليتهمــا املعتبــرة‬\n‫شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات مــا نســب‬\n‫إليهمــا واحلكــم عليهمــا باآلتــي‪ -1 :‬بحــد املســكر للثانــي لقــاء شــربه‬\n‫لــه‪ -2‬بعقوبــة تعزيريــة بحقهمــا لتســتر األول علــى الثانــي وحليــازة الثانــي‬\n‫للمســكر بقصــد الشــرب‪ .‬هــذه دعــواي وبعرضهــا علــى املدعــى عليهمــا‬\n‫ا مــا ذكــره املدعــي العــام مــن القبــض‬   ‫أجــاب املدعــى عليــه علــي قائ ـ ً‬\n‫علــي يف التاريــخ املذكــور وأننــي كنــت يف حالــة ســكر وأنــه عثــر‬\n‫بحوزتــي علــى قــارورة مــاء حتتــوي علــى قليــل مــن املســكر وكأس بــه‬\n‫بعــض املســكر وأنهــا تعــود لــي بقصــد الشــرب كمــا أجــاب املدعــى‬\n\n\n                                                                                     ‫‪194‬‬\n\f      ‫ا مــا ذكــره املدعــي العــام مــن القبــض علــي يف التاريــخ‬    ‫عليــه ‪.....‬قائ ـ ً‬\n      ‫املذكــور أثنــاء قيادتــي للســيارة يرافقنــي املدعــى عليــه ‪.....‬وأنــه عثــر‬\n      ‫بحوزتــه علــى القــارورة والــكأس املذكــور صحيــح لكننــي لــم أكــن‬\n      ‫أعلــم أنــه يف حالــة ســكر وأن مــا بحوزتــه مســكر وقــد اتصــل بــي‬\n      ‫يومهــا وأخبرنــي بأنــه متعطــل وطلــب إيصالــه مــن الدمــام إلــى القطيــف‬\n      ‫وقبــض علــي يف نقطــة التفتيــش والســوابق التــي علــي صحيحــه ولكنهــا‬\n      ‫قدميــة هكــذا أجــاب فجــرى ســؤال املدعــي العام هــل كان املدعى عليه‬\n      ‫علــي مطلوبـ ًا ألي مــن اجلهــات األمنيــة أو القضائيــة قــال ال فجــرى ســؤال‬\n      ‫األطــراف ألديهــم مــا يريــدون إضافتــه فقــال كل واحــد منهــم ليــس لدي‬\n      ‫مــا أضيفــه وبتصفــح املعاملــة جــرى االطــاع علــى التقريــر الكيمــاوي‬\n      ‫املشــار لــه أعــاه فوجدتــه كما ذكر املدعــي العام كما جرى االطالع‬\n      ‫علــى ســوابق املدعــى عليــه مجتبــى املرصــودة يف قــرار االتهــام مرفــق‬\n      ‫ـاء‬\n      ‫لفــة (‪ )17‬فوجــدت أن الســابقتني بتاريــخ ‪1426‬ه ـ ‪1427 ،‬ه ـ ‪ .‬فبنـ ً‬\n      ‫علــى مــا تقــدم وحيــث تتلخــص دعــوى املدعــي العــام يف اتهــام املدعــى‬\n      ‫عليــه علــي بشــرب املســكر وحيازتــه لقــارورة مــاء صحــة حتتــوي علــى‬\n      ‫(‪)100‬ملــم مــن املســكر وكأس بــه الربــع مــن املســكر بقصــد الشــرب‬\n      ‫واتهــام املدعــى عليــه ‪.....‬بالتســتر عليــه وألن هــذه احملكمــة مختصــة‬\n      ‫بنظــر هــذه الدعــوى بنــاء علــى املــواد(‪ )128-131‬مــن نظــام اإلجــراءات‬\n      ‫اجلزائيــة وإلقــرار املدعــى عليــه ‪.....‬وهــو بكامــل أهليتــه بجميــع مــا جــاء‬\n      ‫يف دعــوى املدعــي العــام وألن اإلقــرار حجــة علــى املقــر وألن مــا أقــدم‬\n      ‫عليــه فعــل محــرم شــرع ًا لقولــه تعالــى ((إمنــا اخلمــر وامليســر واألنصــاب‬\n      ‫واألزالم رجــس مــن عمــل الشــيطان فاجتنبــوه)) املائــدة‪ 90:‬ولقولــه‬\n      ‫صلــى اهلل عليــه وســلم (( إن اهلل لعــن اخلمــر وعاصرهــا ومعتصرهــا‬\n\n\n‫‪195‬‬\n\f‫وشــاربها وحاملهــا واحملمولــة إليــه )) رواه احلاكــم ‪ ،‬و ملــا نــص عليــه‬\n‫جماهيــر أهــل العالــم مــن أن حــد شــرب املســكر ثمانــن جلــدة وهــو مــا‬\n‫انتهــى إليــه قــرار هيئــة كبــار العلمــاء باململكــة ذي الرقــم رقــم ‪53‬يف‬\n‫‪1397/4/4‬ه ـ ‪ .‬وألن الثابــت مــن وقائــع الدعــوى وجــواب املدعــي العــام‬\n‫أن املدعــى عليــه ‪.....‬لــم يتعمــد إخفــاء املدعــى عليــه ‪.....‬أو كتــم خبــره‬\n‫بــل إن املدعــى عليــه ‪.....‬لــم يكــن متهمــا ً أو مطلوبـ ًا لــدى أي مــن اجلهــات‬\n‫األمنيــة أو القضائيــة وبهــذا ينتفــي حتقــق أي ركــن مــن أركان جرميــة‬\n‫التســتر اجلنائــي فيمــا قــام بــه املدعــى عليــه ‪.....‬مــن إركاب شــخص معــه‬\n‫يف ســيارته إليصالــه وألن األصــل بــراءة املتهــم وجلميــع مــا ســبق فقــد‬\n‫حكمــت باآلتــي ‪ :‬أو ًال ‪ :‬ثبــوت إدانــة املدعــى عليــه احلاضــر ‪.....‬بشــرب‬\n‫املســكر وحيــازة قــارورة مــاء صحــة وكأس يحتويــان علــى بعــض‬\n‫املســكر بقصــد الشــرب ثاني ـ ًا ‪ :‬جلــد املدعــى عليــه ‪.....‬ثمانــن جلــدة‬\n‫دفعــة واحــدة علنـ ًا حــد شــرب املســكر ‪ ،‬وجلــده عشــرين جلــدة تعزيــر ًا‬\n‫علــى حيــازة املســكر ‪ .‬ثالثـ ُا ‪ :‬بــراءة املدعــى عليــه ‪.....‬من التهمة املنســوبة‬\n‫إليــه وبإعــان احلكــم قــرر املدعــى عليهمــا القناعــة وقــرر املدعــي العــام‬\n‫اعتراضــه وطلــب رفــع املعاملــة حملكمــة االســتئناف دون تقــدمي الئحــة‬\n          ‫اعتراضيــة وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/34/1311900‬ج‪ 2‬وتاريــخ ‪1434/05/29‬ه ـ‬\n‫الــواردة مــن فضيلــة‪ /‬رئيــس احملكمــة اجلزائيــة مبحافظــة القطيــف‬\n‫الشــيخ ‪.....‬برقــم ‪ 34939684‬وتاريــخ ‪1434/05/26‬ه ـ املرفــق بهــا‬\n‫القــرار الصــادر مــن فضيلتــه املســجل برقــم ‪ 34217683‬وتاريــخ‬\n\n\n                                                                                         ‫‪196‬‬\n\f      ‫كل مــن‪...../1‬‬  ‫‪1434/05/20‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد ٍ‬\n      ‫و‪..... /2‬يف قضيــة مســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو‬\n      ‫مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫قررنــا املصادقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                       ‫محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/06/07‬ه ـ ‪.‬‬\n\n\n\n\n‫‪197‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":192,"source_page_end":197,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e5813947e6a71d229a0e944cc020e51a4ee6ed35795015777ada0f7ab4f86cc9","normalized_text_hash":"b09df55233eed7112464f9cb574150fd8dd214fe10422f280f0dfdbdd4057414","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p192-34217683"},{"id":"260ba883-f129-5be3-ad32-958d75869dfd","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -هروب املدعى عليه من رجال األمن -الذمي ال يحد بشرب اخلمر -التعزير باجللد يف مكان عام .","document_number":"34231311","case_number":"34191499","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/5","year":"1434","subject":"مسكر -شرب املسكر -هروب املدعى عليه من رجال األمن -الذمي ال يحد بشرب اخلمر -التعزير باجللد يف مكان عام .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك ‪ 34231311:‬تاريخه‪1434/6/5:‬هـ‬\n                  ‫رقم الدعوى‪34191499:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n         ‫‪ 34266155‬تاريخه‪1434/07/11:‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب املســكر ‪ -‬هــروب املدعــى عليــه مــن رجــال األمــن ‪ -‬الذمــي‬\n               ‫ال يحــد بشــرب اخلمــر ‪ -‬التعزيــر باجللــد يف مــكان عــام ‪.‬‬\n\n\n\n‫‪ -1‬مــا رواه أبــو هريــرة أنــه صلــى اهلل عليــه وســلم قــال ( ومــن هــم بســيئة‬\n              ‫فلــم يعملهــا لــم تكتــب وإن عملهــا كتبــت ) أخرجــه مســلم ‪.‬‬\n‫‪ -2‬قــال ابــن قدامــة يف املقنــع ‪ (429/26‬والذمــي ال يحــد بشــربه يف‬\n                                                                      ‫الصحيــح)‪.‬‬\n ‫‪ -3‬قال يف الشرح الكبير ‪( 429/26‬ألنه يعتقد حله فلم يحد بفعله)‪.‬‬\n‫‪ -4‬قــال املــرداوي يف اإلنصــاف ‪ ( 430/26‬قــال يف البلغــة ولــو رضــي‬\n                 ‫بحكمنــا ألنــه لــم يلتــزم االنقيــاد يف مخالفــة دينــه ) ‪.‬‬\n‫‪ -5‬قــال شــيخ اإلســام يف مجمــوع الفتــاوى ‪ ( 664/28‬وعلــى هــذا فــإذا‬\n‫كانــوا ال ينتهــون عــن إظهــار اخلمــر أو معاونــة املســلمني عليهــا أو‬\n‫بيعهــا وهديهــا للمســلمني إال بإراقتهــا عليهــم فإنهــا تــراق عليهــم مــع‬\n                                                              ‫مــا يعاقبــون بــه) ‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه وافــد غيــر مســلم بشــربه‬\n‫للمســكر ومحاولتــه الهــروب مــن رجــال األمــن وطلــب إثبــات مــا نســب‬\n‫إليــه ومعاقبتــه تعزيــر ًا ومصادقــة املدعــى عليــه بواســطة املترجــم علــى‬\n                                                                                       ‫‪198‬‬\n\f      ‫شــرب املســكر وإنــكار الهــروب مــن رجــال األمــن ‪،‬وملــا تقــرر مــن‬\n      ‫عــدم إقامــة حــد املســكر علــى ذمــي إذا شــرب ‪،‬وبنــاء علــى مــا تقــدم‬\n      ‫حكمــت احملكمــة بتعزيــره بجلــده ثالثــن جلــدة علنـ ًا يف مــكان عــام‬\n      ‫لشــربه املســكر وقنــع املدعــى عليــه واعتــرض املدعــي العــام بــدون‬\n                          ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬  ‫الئحــة ُ‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ .....‬القاضــي باحملكمــة اجلزائيــة‬\n      ‫بالقطيــف بنــاء علــى املعاملــة احملالــة إلــي مــن فضيلــة الرئيــس برقــم‬\n      ‫‪ 34191499‬يف ‪1434/4/27‬ه ـ والــواردة بكتــاب رئيــس دائــرة‬\n      ‫التحقيــق واالدعــاء العــام مبحافظــة القطيــف بكتابــه ذي الرقــم ه‬\n      ‫ق‪ 2862/2/4‬يف ‪1434/4/24‬ه ـ حضــر املدعــي العــام ‪.....‬مبوجــب‬\n      ‫كتــاب التكليــف رقــم ‪.....‬يف ‪1431/9/15‬ه ـ وادعــى علــى احلاضــر‬\n      ‫معــه ‪.....‬الهنــدي اجلنســية غيــر مســلم الديانــة واملقيــم يف البــاد مبوجــب‬\n      ‫ا يف دعــواه إنــه بتاريــخ ‪1434/2/19‬ه ـ مت‬      ‫رخصــة اإلقامــة رقــم ‪.....‬قائـ ً‬\n      ‫مشــاهدة املدعــى عليــه بالقــرب مــن مركــز حــرس احلــدود وهــو بحالــة‬\n      ‫غيــر طبيعيــة فتــم القبــض عليــه ثــم قــام بالهــرب إال انــه مت الســيطرة‬\n      ‫والقبــض عليــه‪ .‬وباستشــمامه تبــن انبعــاث رائحــة املســكر منــه‬\n      ‫وباســتجوابه اقــر بقيامــه بشــرب املســكر قبــل القبــض عليــه وبهروبــه‬\n      ‫مــن رجــال األمــن وقــد أســفر التحقيــق معــه عــن اتهامــه بشــرب املســكر‬\n      ‫ومحاولــة الهــرب مــن رجــال األمــن وبالبحــث عــن ســوابقه علــى املســتوى‬\n      ‫العــام لــم تــرد حتــى تاريخــه‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور‪ .‬وهــو‬\n      ‫بكامــل أهليتــه املعتبــرة شــرع ًا ‪ ،‬فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا‬\n\n‫‪199‬‬\n\f‫أطلــب إثبــات مــا نســب إليــه واحلكــم عليــه بعقوبــة تعزيرية تزجــره وتردع‬\n‫غيــره هــذا مــا ادعــى بــه وبعرضــه علــى املدعــى عليــه وبســؤاله عنــه عــن‬\n‫طريــق مترجــم لغتــه ‪.....‬ســيرلنكي اجلنســية مســلم الديانــة واملقيــم يف‬\n‫ا مــا ذكــره املدعــي‬ ‫البــاد مبوجــب رخصــة اإلقامــة رقــم ‪.....‬أجــاب قائـ ً‬\n‫العــام مــن شــربي للمســكر صحيــح ومــا ذكــره مــن محاولــة هروبــي‬\n‫مــن رجــال األمــن غيــر صحيــح هــذا مــا أجــاب بــه وبســؤال املدعــى عليــه‬\n‫ا‬\n‫عــن طريــق مترجــم لغتــه عــن موضــع شــربه للمســكر أجــاب قائ ـ ً‬\n‫لقــد شــربته عنــد شــاطئ البحــر قريب ـ ًا مــن املينــاء هــذا مــا أجــاب بــه‬\n‫ا إنــه نصرانــي الديانــة هــذا مــا أجــاب‬      ‫وبســؤاله عــن دينــه أجــاب قائ ـ ً‬\n‫ا لقــد كان‬   ‫ا أجــاب قائ ـ ً‬‫بــه وبســؤاله هــل كان شــربه لــه نهــار ًا أم لي ـ ً‬\n‫شــربي لــه عنــد الســاعة اخلامســة مســاء ًا هــذا مــا أجــاب بــه فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه بشــربه للمســكر‬\n‫يف مــكان عــام وملــا قــرره األصحــاب رحمهــم اهلل مــن عــدم إقامــة حــد‬\n‫املســكر علــى ذمــي إذا شــرب قــال ابــن قدامــة يف املقنــع املطبــوع مــع‬\n‫الشــرح ‪ : 429/26‬والذمــي ال يحــد بشــربه يف الصحيــح أ‪.‬ه ـ قــال يف‬\n‫الشــرح ‪ : 429/26‬ألنــه يعتقــد حلــه فلــم يحــد بفعلــه أ‪.‬ه ـ وقــال املــرداوي‬\n‫يف اإلنصــاف املطبــوع مــع الشــرح ‪ : 430/26‬قــال يف البلغــة ولــو رضــي‬\n‫بحكمنــا ألنــه لــم يلتــزم االنقيــاد يف مخالفــة دينــه أ‪.‬ه ـ وقــد قــرر شــيخ‬\n‫اإلســام رحمهــم اهلل معاقبــة مــن شــرب املســكر منهــم متــى مــا أظهــر‬\n‫شــربه بــن املســلمني قــال رحمــه اهلل وعلــى هــذا فــإذا كانــوا ال ينتهــون‬\n‫عــن إظهــار اخلمــر أو معاونــة املســلمني عليهــا أو بيعهــا وهديهــا للمســلمني‬\n‫إال بإراقتهــا عليهــم فإنهــا تــراق عليهــم مــع مــا يعاقبــون بــه أ‪.‬ه ـ مجمــوع‬\n‫الفتــاوى ‪ 664/28‬وإلنــكار املدعــى عليــه محاولــة هروبــه مــن رجــال‬\n\n\n                                                                                         ‫‪200‬‬\n\f      ‫األمــن ومــع فــرض ثبوتهــا فــا تتجــه املعاقبــة ملجــرد محاولتــه وهمــه‬\n      ‫ويف حديــث أبــي هريــرة رضــي اهلل عنــه يف صحيــح مســلم أن النبــي‬\n      ‫صلــى اهلل عليــه وســلم قــال (ومــن هــم بســيئة فلــم يعملهــا لــم تكتــب وإن‬\n      ‫عملهــا كتبــت) لــذا فقــد ثبــت لــدي شــرب املدعــى عليــه للمســكر يف‬\n      ‫مــكان عــام وقــررت تعزيــره بجلــده عــدد ثالثــن جلــدة علنـ ًا يف مــكان‬\n      ‫عــام لشــربه للمســكر يف مــكان عــام وبــه حكمــت وبعــرض احلكــم‬\n      ‫علــى الطرفــن اعتــرض عليــه املدعــي العــام وطلــب اســتئنافه دون تقــدمي‬\n      ‫الئحــة اعتراضيــة وقنــع بــه املدعــى عليــه وســيتم بعــث كامــل املعاملــة‬\n      ‫حملكمــة االســتئناف لتدقيــق احلكــم حســب املتبــع وللبيــان حــرر يف‬\n      ‫‪1434/6/5‬ه ـ وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                                 ‫أجمعــن ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة القطيــف برقــم‬\n      ‫‪ 341022753‬وتاريــخ ‪1434/6/11‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n      ‫‪ 341478205‬وتاريــخ ‪1434/6/19‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n      ‫فضيلــة القاضــي باحملكمــة الشــيخ ‪.....‬املســجل برقــم ‪34231311‬‬\n      ‫وتاريــخ ‪1434/6/5‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضد‪...../‬هنــدي‬\n      ‫اجلنســية يف قضيــة مســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو‬\n      ‫مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n      ‫قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                      ‫وآلــه وصحبــه وســلم حــرر يف ‪1434/7/8‬ه ـ ‪.‬‬\n\n\n\n‫‪201‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":198,"source_page_end":201,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bfd38bcddb7f0be61ea12878f257b8516a7841e918cad3a183a3378ad81379d9","normalized_text_hash":"56f08a018c9adf2d09e058b2dfe4846523299df3cf5c41eaa9efe921fa6cb7c1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p198-34231311"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

